def decode_cyclic(s: str) -> str:
    """
    Takes as input string encoded with encode_cyclic function.
    Returns decoded string.
    """
    groups = [
        s[(3 * i):min((3 * i + 3), len(s))]
        for i in range((len(s) + 2) // 3)
    ]
    groups = [
        (group[-1] + group[:-1]) if len(group) == 3 else group
        for group in groups
    ]
    return "".join(groups)

