def split_words(txt):
    """
    Given a string of words, return a list of words split on whitespace.
    If no whitespace exists, split on commas. If no commas exist, return the
    number of lower-case letters whose alphabet order is odd
    (a=0, b=1, ..., z=25).
    """
    if not txt:
        return []

    if any(ch.isspace() for ch in txt):
        return txt.split()

    if "," in txt:
        return txt.split(",")

    return sum(
        1
        for ch in txt
        if "a" <= ch <= "z" and (ord(ch) - ord("a")) % 2 == 1
    )

