def valid_date(date):
    """
    Validate a date string in the format mm-dd-yyyy.

    Returns True if the date is valid, otherwise False.
    """
    if not isinstance(date, str) or not date:
        return False

    parts = date.split("-")
    if len(parts) != 3:
        return False

    month_str, day_str, year_str = parts

    if len(month_str) != 2 or len(day_str) != 2 or len(year_str) != 4:
        return False

    def all_digits(s):
        return all(ch in "0123456789" for ch in s)

    if not (all_digits(month_str) and all_digits(day_str) and all_digits(year_str)):
        return False

    month = int(month_str)
    day = int(day_str)

    if month < 1 or month > 12:
        return False

    if month in (1, 3, 5, 7, 8, 10, 12):
        return 1 <= day <= 31

    if month in (4, 6, 9, 11):
        return 1 <= day <= 30

    if month == 2:
        return 1 <= day <= 29

    return False

