def minPath(grid, k):
    """
    Return the lexicographically smallest ordered list of values visited by
    a path of length k in the grid.
    """
    if k <= 0:
        return []
    if not grid or not grid[0]:
        return []

    # Find the globally smallest value. In the given problem this is always 1.
    min_val = grid[0][0]
    start_r = start_c = 0

    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val < min_val:
                min_val = val
                start_r, start_c = r, c

    if k == 1:
        return [min_val]

    # From the smallest cell, the second value must be the smallest neighbor.
    directions = ((1, 0), (-1, 0), (0, 1), (0, -1))
    best_neighbor = None

    for dr, dc in directions:
        nr, nc = start_r + dr, start_c + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[nr]):
            val = grid[nr][nc]
            if best_neighbor is None or val < best_neighbor:
                best_neighbor = val

    # The problem guarantees N >= 2, so a neighbor should always exist.
    if best_neighbor is None:
        return [min_val] * k

    # The optimal path alternates between the global minimum and its smallest
    # neighbor, because from that neighbor the global minimum is always the
    # smallest possible next cell.
    path = [min_val] * k
    for i in range(1, k, 2):
        path[i] = best_neighbor

    return path

