import math
def right_angle_triangle(a, b, c):
    """
    Given the lengths of the three sides of a triangle, return True if the
    three sides form a right-angled triangle, False otherwise.
    """
    # Use exact integer arithmetic for plain integer inputs.
    if all(isinstance(v, int) and not isinstance(v, bool) for v in (a, b, c)):
        if a <= 0 or b <= 0 or c <= 0:
            return False

        x, y, z = sorted((a, b, c))
        return x + y > z and x * x + y * y == z * z

    # For other numeric inputs, compare with a small relative tolerance.
    try:
        x, y, z = sorted(float(v) for v in (a, b, c))
    except (TypeError, ValueError, OverflowError):
        return False

    if not (math.isfinite(x) and math.isfinite(y) and math.isfinite(z)):
        return False

    if x <= 0 or y <= 0 or z <= 0:
        return False

    if x + y <= z:
        return False

    return math.isclose(math.hypot(x, y), z, rel_tol=1e-9, abs_tol=0.0)

