def do_algebra(operator, operand):
    """
    Evaluate an algebraic expression built from the given operand integers
    and operator strings.

    Supported operators: +, -, *, //, **
    Precedence follows standard Python arithmetic rules:
        ** (right-associative)
        * and //
        + and -
    """
    if not operand:
        return 0
    if not operator:
        return operand[0]

    precedence = {
        "+": 1,
        "-": 1,
        "*": 2,
        "//": 2,
        "**": 3,
    }

    values = [operand[0]]
    ops = []

    def apply_operator(op):
        right = values.pop()
        left = values.pop()

        if op == "+":
            values.append(left + right)
        elif op == "-":
            values.append(left - right)
        elif op == "*":
            values.append(left * right)
        elif op == "//":
            values.append(left // right)
        elif op == "**":
            values.append(left ** right)
        else:
            raise ValueError(f"Unsupported operator: {op}")

    for i, op in enumerate(operator):
        op = op.strip()

        if op not in precedence:
            raise ValueError(f"Unsupported operator: {op}")

        while ops:
            top = ops[-1]

            if (
                precedence[top] > precedence[op]
                or (precedence[top] == precedence[op] and op != "**")
            ):
                apply_operator(ops.pop())
            else:
                break

        ops.append(op)
        values.append(operand[i + 1])

    while ops:
        apply_operator(ops.pop())

    return values[0]

